package ug.audiocity.studio;
import java.io.*;import java.nio.file.*;import java.util.*;
public final class PatternReviewTests {
 static int n;static void ok(boolean b,String why){n++;if(!b)throw new AssertionError(why);}static void clean(File f){if(f.isDirectory())for(File c:f.listFiles())clean(c);f.delete();}
 public static void main(String[] args)throws Exception{
  File dir=Files.createTempDirectory("acs-pattern-review-").toFile();try{
   Core.Session session=new Core.Session();session.directory=dir.getAbsolutePath();session.bpm=240;BeatPilotDrumPattern draft=new BeatPilotDrumPattern(240,2);draft.set(0,0,0,100);draft.set(1,1,4,87);PatternLibrary.Entry entry=PatternLibrary.add(session,"Verse",draft);float[][] kit=new float[8][];for(int l=0;l<8;l++){kit[l]=new float[400];Arrays.fill(kit[l],.1f*(l+1));}
   PatternArrangement.place(session,entry.id,kit,0,2);Core.Track kick=session.tracks.get(0);Core.Clip selected=kick.clips.get(1);selected.gain=.37;selected.offset=100;selected.length=2400;selected.envelopeOffset=100;
   draft.set(0,0,1,103);Map<Core.Clip,Core.Clip> updated=PatternArrangement.save(session,entry.id,"Verse",draft,kit);Core.Clip selectedNow=updated.get(selected);ok(selectedNow!=null&&kick.clips.contains(selectedNow),"selected clip maps to the live replacement after pattern save");ok(selectedNow.start==selected.start&&selectedNow.offset==100&&selectedNow.length==2400&&selectedNow.gain==.37,"selection remap retains the exact independent instance and its edits");ok(updated.size()==16,"all eight lanes and both repeats receive replacements");ok(!updated.containsKey(new Core.Clip("Unrelated",new Core.Memory(new float[20]),"",0)),"unrelated selection is unchanged");
   PatternDraft captured=new PatternDraft(entry.id,"Verse",draft);draft.set(1,1,4,0);draft.setSampleChoice(0,0);ok(!captured.matches(entry.id,"Verse",draft),"later edits stay dirty when an older background save finishes");ok(captured.pattern().get(1,1,4)==87,"queued draft is isolated from later UI edits");BeatPilotDrumPattern leaked=captured.pattern();leaked.set(0,0,0,0);ok(captured.pattern().get(0,0,0)==100,"reading a draft cannot mutate a queued save");
   Map<Core.Clip,Core.Clip> background=captured.save(session,kit);ok(background.containsKey(selectedNow),"background save provides a second valid selection remap");Core.Session reopened=AudioIO.load(dir);BeatPilotDrumPattern restored=PatternLibrary.pattern(reopened,PatternLibrary.find(reopened,entry.id));ok(restored.get(1,1,4)==87&&restored.get(0,0,1)==103,"unsaved manual edits survive background persistence and reopen");ok(captured.matches(entry.id,"Verse",restored),"matching saved draft can clear dirty state");ok(!captured.matches("other","Verse",restored)&&!captured.matches(entry.id,"Renamed",restored),"a save never clears edits from another pattern or name");ok(reopened.tracks.size()==8&&reopened.tracks.get(0).clips.size()==2,"background save preserves separate tracks and repeat count");
   String stable=PatternLibrary.find(session,entry.id).data;Core.Clip prior=kick.clips.get(0);try{PatternArrangement.save(session,entry.id,"Broken",draft,new float[8][]);throw new AssertionError("missing kit accepted");}catch(IllegalArgumentException|IOException expected){n++;}ok(kick.clips.get(0)==prior&&PatternLibrary.find(session,entry.id).data.equals(stable),"failed rendering leaves previous clips and pattern intact");
   java.util.concurrent.ExecutorService writers=java.util.concurrent.Executors.newFixedThreadPool(4);java.util.List<java.util.concurrent.Future<?>> writes=new ArrayList<>();try{for(int i=0;i<24;i++){Core.Session version=reopened.copy();version.title="Concurrent save "+i;writes.add(writers.submit(()->{try{ProjectIO.save(version);}catch(Exception e){throw new RuntimeException(e);}}));}for(java.util.concurrent.Future<?> write:writes)write.get();Core.Session concurrent=AudioIO.load(dir);ok(concurrent.title.startsWith("Concurrent save ")&&concurrent.tracks.size()==8,"overlapping saves produce one complete valid project");}finally{writers.shutdownNow();}
   ByteArrayOutputStream bytes=new ByteArrayOutputStream();AudioIO.backup(bytes,reopened);File restore=new File(dir,"restore");restore.mkdir();Core.Session backup=AudioIO.restore(new ByteArrayInputStream(bytes.toByteArray()),restore);ok(PatternLibrary.pattern(backup,PatternLibrary.find(backup,entry.id)).encode().equals(restored.encode()),"background-persisted patterns survive portable backup too");
  }finally{clean(dir);}System.out.println("PatternReviewTests passed "+n+" checks");
 }
}
